"""Pixel-art sprites generated by scripts/make_sprites.py. Do not edit."""

from badgeware import *


def _decode(hexdata):
    raw = bytearray(len(hexdata) // 2)
    for i in range(0, len(hexdata), 2):
        raw[i // 2] = int(hexdata[i:i + 2], 16)
    return raw


def _draw(w, h, pal, hexdata, x0, y0, scale):
    pens = [color.rgb(r, g, b) for (r, g, b) in pal]
    raw = _decode(hexdata)
    for i in range(0, len(raw), 4):
        y, x, ln, ci = raw[i], raw[i + 1], raw[i + 2], raw[i + 3]
        screen.pen = pens[ci]
        screen.rectangle(x0 + x * scale, y0 + y * scale,
                         ln * scale, scale)


def draw_icon(name, x, y, small=False):
    """Draw a pixel-art icon at (x, y): 24x24, or 12x12 if small."""
    w, h, pal, hexdata = (ICONS_SM if small else ICONS)[name]
    _draw(w, h, pal, hexdata, x, y, 1)


def draw_splash(frame):
    """Draw an 80x60 splash frame scaled 4x to fullscreen."""
    w, h, pal, hexdata = SPLASH_FRAMES[frame % len(SPLASH_FRAMES)]
    _draw(w, h, pal, hexdata, 0, 0, 4)


